import React,{useMemo,useState} from 'react';
import {textDiff} from './text-diff.js';
function UnchangedText({chunk}){const [open,setOpen]=useState(false);return <details className="diff-unchanged" onToggle={e=>setOpen(e.currentTarget.open)}><summary>{chunk.lineCount} 行未变化</summary>{open&&<pre>{chunk.text}</pre>}</details>;}
export function DiffDisclosure(props){const [open,setOpen]=useState(false);return <details onToggle={e=>setOpen(e.currentTarget.open)}><summary>比较前后版本</summary>{open&&<TextDiff {...props}/>}</details>;}
export function TextDiff({before='',after='',beforeLabel='修改前',afterLabel='修改后'}){
 const result=useMemo(()=>textDiff(before,after),[before,after]),[full,setFull]=useState(false),changed=result.added>0||result.removed>0;
 return <section className="text-diff" aria-label="增删改比较"><header><strong>{beforeLabel} → {afterLabel}</strong><button type="button" aria-pressed={full} onClick={()=>setFull(!full)}>{full?'只看变化':'显示全文'}</button></header><div className="diff-legend"><span>＋ 新增 {result.added} 字符</span><span>− 删除 {result.removed} 字符</span><small>{result.blockStats?'按文本块统计；含换行与空白':'含换行与空白'}</small></div>{result.coarse&&<p className="diff-note">变化范围较大，按文本块比较；两份原文均完整保留。</p>}{!changed?<p className="diff-note">两份内容一致。</p>:result.chunks.map((chunk,i)=>!full&&chunk.kind==='same'?<UnchangedText key={i} chunk={chunk}/>:<div className={`diff-block kind-${chunk.kind}`} key={i}><span className="diff-line-number" title={`原文行 ${chunk.oldLine??'—'}，对照行 ${chunk.newLine??'—'}`}>{chunk.oldLine??'·'}<br/>{chunk.newLine??'·'}</span><span className="diff-marker" aria-label={chunk.kind==='add'?'新增':chunk.kind==='remove'?'删除':'未变化'}>{chunk.kind==='add'?'+':chunk.kind==='remove'?'−':' '}</span><pre>{chunk.inline?chunk.inline.map((part,j)=>part.kind==='same'?<React.Fragment key={j}>{part.text}</React.Fragment>:chunk.kind==='add'?<ins key={j}>{part.text}</ins>:<del key={j}>{part.text}</del>):chunk.text}</pre></div>)}</section>;
}
export const diffStyles=`
.cuigengji .text-diff{margin:12px 0;border:1px solid var(--cg-line);border-radius:9px;overflow:hidden;min-width:0;max-width:100%;background:var(--cg-paper)}
.cuigengji .text-diff>header{display:flex;align-items:center;gap:8px;padding:10px 12px;border-bottom:1px solid var(--cg-line);min-width:0}.cuigengji .text-diff>header strong{flex:1;font-size:12px;overflow-wrap:anywhere;min-width:0}.cuigengji .text-diff>header button{flex:none;font-size:11px;min-height:32px;padding:5px 8px}
.cuigengji .diff-legend{display:flex;flex-wrap:wrap;gap:6px 14px;padding:8px 12px;color:var(--cg-muted);font-size:11px}.cuigengji .diff-note{padding:0 12px;font-size:12px;color:var(--cg-muted)}
.cuigengji .diff-block{display:flex;align-items:stretch;min-width:0;border-top:1px solid var(--cg-line)}.cuigengji .diff-line-number{width:38px;flex:none;padding:9px 4px;font:10px/1.6 Consolas,monospace;color:var(--cg-muted);text-align:right;background:var(--cg-wash)}.cuigengji .diff-marker{width:20px;flex:none;padding-top:9px;text-align:center;font-weight:700}
.cuigengji .diff-block pre,.cuigengji .diff-unchanged pre{white-space:pre-wrap;overflow-wrap:anywhere;word-break:normal;min-width:0;flex:1;margin:0;padding:8px 10px;border:0;border-radius:0;font:13px/1.8 Consolas,'Microsoft YaHei',monospace;color:var(--cg-ink);background:transparent;tab-size:4}
.cuigengji .diff-block.kind-add{background:color-mix(in srgb,#16a34a 9%,var(--cg-paper))}.cuigengji .diff-block.kind-remove{background:color-mix(in srgb,#dc6262 9%,var(--cg-paper))}.cuigengji .kind-add .diff-marker{color:#16a34a}.cuigengji .kind-remove .diff-marker{color:#dc6262}.cuigengji .diff-block ins{background:color-mix(in srgb,#16a34a 24%,transparent);text-decoration:none;font-weight:600}.cuigengji .diff-block del{background:color-mix(in srgb,#dc6262 24%,transparent);text-decoration:line-through;text-decoration-thickness:1px}
.cuigengji .diff-unchanged{margin:0;border-top:1px solid var(--cg-line);padding:0}.cuigengji .diff-unchanged summary{padding:9px 12px;color:var(--cg-muted);font-size:11px;cursor:pointer}.cuigengji .history-merge-edit textarea{min-height:180px}
`;
